<?php
if (! defined('ABSPATH')) exit;
final class StoreV1_Updater { const API='https://api.github.com/repos/DouglasReisofc/storev1-theme/releases/latest'; const SLUG='storev1-theme'; public static function boot(){ add_filter('pre_set_site_transient_update_themes',[__CLASS__,'check']); add_filter('themes_api_result',[__CLASS__,'info'],10,3); } private static function release(){ $r=wp_remote_get(self::API,['timeout'=>8,'headers'=>['Accept'=>'application/vnd.github+json','User-Agent'=>'StoreV1-Theme-Updater']]); if(is_wp_error($r)||wp_remote_retrieve_response_code($r)!==200)return null; return json_decode(wp_remote_retrieve_body($r),true); } public static function check($t){ if(!is_object($t))$t=new stdClass(); $r=self::release(); if(!$r||empty($r['tag_name']))return $t; $v=ltrim($r['tag_name'],'v'); $zip=!empty($r['zipball_url'])?$r['zipball_url']:''; if(version_compare($v,wp_get_theme()->get('Version'),'>'))$t->response[self::SLUG]=['theme'=>self::SLUG,'new_version'=>$v,'url'=>'https://github.com/DouglasReisofc/storev1-theme','package'=>$zip]; return $t; } public static function info($res,$action,$args){ if($action!=='theme_information'||empty($args->slug)||$args->slug!==self::SLUG)return $res; $r=self::release(); if(!$r)return $res; $res=(object)['name'=>'StoreV1 Theme','slug'=>self::SLUG,'version'=>ltrim($r['tag_name'],'v'),'homepage'=>'https://github.com/DouglasReisofc/storev1-theme','download_link'=>$r['zipball_url'],'sections'=>['description'=>'Tema responsivo para WooCommerce.']]; return $res; } }
StoreV1_Updater::boot();
